pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address admin, bool access) public {
        vm.assume(caller != address(this));
        vm.assume(admin != address(this));
        vm.assume(admin != address(0));

        // Make admin an admin
        c.adjustAdminAccess(admin, true);

        // Check that supportsInterface returns true for the expected interface
        bool before = c.supportsInterface(type(IERC1155).interfaceId);

        // Now call adjustAdminAccess with the reference contract's permission guard
        // We need to call as owner to change admin
        vm.prank(address(this));
        c.adjustAdminAccess(caller, access);

        bool after = c.supportsInterface(type(IERC1155).interfaceId);

        // The general rule: supportsInterface for IERC1155 always returns true
        assertTrue(before == true && after == true);
    }
}

